/**
 * M3 bootstrap layer: boots a single flows.json file through the real
 * @node-red/runtime (no HTTP server, no editor/admin API) so its nodes are
 * fully live, and computes a canonicalized-content `flowVersion` hash.
 *
 * No Temporal involved here. Mirrors the minimal real init sequence used by
 * the production `node-red` CLI (packages/node_modules/node-red/lib/red.js):
 * `redUtil.init(settings)` then `runtime.init(settings, httpServer)` with
 * `httpAdminRoot: false` to skip the editor/admin API entirely.
 */

"use strict";

const path = require("path");
const fs = require("fs");
const os = require("os");
const crypto = require("crypto");

// eslint-disable-next-line global-require
const runtime = require("../../../@node-red/runtime");
// eslint-disable-next-line global-require
const redUtil = require("../../../@node-red/util");

/** Deep-sort object keys (recursively) so key order never affects hashing. */
function canonicalize(value) {
    if (Array.isArray(value)) {
        return value.map(canonicalize);
    }
    if (value && typeof value === "object") {
        const sorted = {};
        Object.keys(value).sort().forEach((key) => {
            sorted[key] = canonicalize(value[key]);
        });
        return sorted;
    }
    return value;
}

/** Content-hash over a canonicalized flow, immune to formatting/key-order. */
function computeFlowVersion(flows) {
    return crypto.createHash("sha256").update(JSON.stringify(canonicalize(flows))).digest("hex");
}

function waitForFlowsStarted() {
    return new Promise((resolve) => {
        redUtil.events.once("flows:started", resolve);
    });
}

// `@node-red/runtime`'s multiplayer module (lib/multiplayer/index.js) registers
// anonymous listeners directly on the shared, process-global `redUtil.events`
// singleton during `runtime.start()` and never removes them - one leaked
// listener per event per `bootstrap()` call, tripping Node's
// MaxListenersExceededWarning after ~11 boots in one process (issue #18).
// There is no upstream hook to opt out of registration or to get a handle
// back, so this snapshots the listener arrays for the exact affected events
// immediately before `runtime.start()` and removes only the ones that were
// newly added by THIS invocation, scoped to this single bootstrap() call.
const MULTIPLAYER_COMMS_EVENTS = [
    "comms:connection-removed",
    "comms:message:multiplayer/connect",
    "comms:message:multiplayer/disconnect",
    "comms:message:multiplayer/location"
];

function snapshotListeners(events, eventNames) {
    const snapshot = {};
    eventNames.forEach((name) => {
        snapshot[name] = events.listeners(name).slice();
    });
    return snapshot;
}

/** Removes only listeners on `events` for each event that are NOT present in `before`. */
function removeListenersAddedSince(events, before, eventNames) {
    eventNames.forEach((name) => {
        const previous = before[name];
        events.listeners(name).forEach((listener) => {
            if (previous.indexOf(listener) === -1) {
                events.removeListener(name, listener);
            }
        });
    });
}

/**
 * Boots `flowFilePath` as the sole flow, headless, through the real runtime.
 * @param {string} flowFilePath - path to a Node-RED flows.json file
 * @param {object} [options]
 * @param {string} [options.userDir] - Node-RED userDir; defaults to a fresh temp dir
 * @param {object} [options.settings] - extra runtime settings, merged over the defaults
 * @returns {Promise<{flowVersion:string, getNode:function(string):object, stop:function():Promise}>}
 */
async function bootstrap(flowFilePath, options) {
    options = options || {};
    const flows = JSON.parse(fs.readFileSync(flowFilePath, "utf8"));
    const flowVersion = computeFlowVersion(flows);

    const storageModule = {
        init: async () => {},
        getFlows: async () => flows,
        getCredentials: async () => ({}),
        saveFlows: async () => {},
        saveCredentials: async () => {}
    };

    const userDir = options.userDir || fs.mkdtempSync(path.join(os.tmpdir(), "node-red-temporal-"));
    const userDirPackageJson = path.join(userDir, "package.json");
    if (!fs.existsSync(userDirPackageJson)) {
        fs.writeFileSync(userDirPackageJson, JSON.stringify({ name: "node-red-temporal-bootstrap", dependencies: {} }));
    }

    const settings = Object.assign(
        {
            httpAdminRoot: false,
            coreNodesDir: path.dirname(require.resolve("../../../@node-red/nodes/package.json")),
            userDir,
            functionGlobalContext: {},
            logging: { console: { level: "warn" } }
        },
        options.settings || {},
        { storageModule }
    );

    redUtil.init(settings);
    runtime.init(settings, null);
    const listenersBeforeStart = snapshotListeners(redUtil.events, MULTIPLAYER_COMMS_EVENTS);
    const started = waitForFlowsStarted();
    await runtime.start();
    await started;

    return {
        flowVersion,
        getNode(id) {
            return runtime._.nodes.getNode(id);
        },
        stop() {
            return runtime.stop().finally(() => {
                removeListenersAddedSince(redUtil.events, listenersBeforeStart, MULTIPLAYER_COMMS_EVENTS);
            });
        }
    };
}

module.exports = { bootstrap, computeFlowVersion };
